// @ts-nocheck
// Hairline figure "ripcord" for theo-marsh-skyfall-2p. Generated by the murder-mystery-story-tree skill via hairline-create.
// Body is the figure file verbatim; edit with: python scripts/art.py unwrap <this> ripcord.js → look.mjs → wrap.
export default function define(HL, hairline) {
/**
 * Ripcord: a packed parachute rig on a packing bench, its harness laid out
 * flat and its ripcord slack over the edge, the handle hanging in the air.
 * The pointer pulls the handle out along the cable, on a spring; once the pin
 * clears, the flaps fall open and the bag rises, on tweens, on a strap cut
 * clean through. The slider is how far the cable pulls out, in world units.
 * The pointer is read against the handle's rest and pulled points on screen,
 * which never move, so a moving cable cannot flip it.
 */
const {
  Cam, clamp, facing, fillet, fit, hull, lerp, open, poly, prism, proj, rad, rings, ringAt, rrect, run,
  spring, stepS, tween, tset, tval, tdone, mk, place, pointer, put, register, disposer, solid,
} = HL;

const BX0 = -40, BX = 176, BY = 96, BZ = 8;
const X0 = 18, X1 = 138, Y0 = 16, Y1 = 80, CH = 20, CR = 10, WT = 2.4, S = 48;
const OPEN = 195, PIN = 0.6, BAG0 = 13, BAG1 = 30, M = 30, LMAX = 72, LIFT = 24;
// The cable at rest: along the seam, over the rim, across the bench and over its edge.
const SLACK = [
  [68, S, CH + 1.1], [X1 - 3, S, CH + 1.1], [X1 + 0.5, S, CH + 0.2], [X1 + 2, S, CH - 2.5], [X1 + 3, S, 3], [X1 + 4.5, S, 0.8],
  [X1 + 8, S, 0.6], [BX - 3, S, 0.6], [BX - 0.5, S, 0.2], [BX + 1, S, -2.5], [BX + 2, S, -10], [BX + 2.2, S, -34],
];
const FRAY = [[0, [[0, 0, 0], [2, 4, -2.5], [2.5, 7.5, -1.5]]], [1, [[0, 0, 0], [1.5, -3.5, -3], [1, -5, -7]]]];
// The handle: a D, its straight bar on the cable.
const D_OUT = fillet([[0, -9], [21, -9], [21, 9], [0, 9]], [1.5, 8, 8, 1.5]);
const D_IN = fillet([[3.2, -5.8], [17.8, -5.8], [17.8, 5.8], [3.2, 5.8]], [1, 5, 5, 1]);

/** n points evenly spaced along a polyline of [x, y, z]. */
function resample(pts, n) {
  const d = [0];
  for (let i = 1; i < pts.length; i++) d.push(d[i - 1] + Math.hypot(...pts[i].map((v, k) => v - pts[i - 1][k])));
  const out = [];
  for (let s = 0, j = 0; s < n; s++) {
    const at = (d[d.length - 1] * s) / (n - 1);
    while (j < pts.length - 2 && d[j + 1] < at) j++;
    const f = clamp((at - d[j]) / (d[j + 1] - d[j]), 0, 1);
    out.push(pts[j].map((v, k) => lerp(v, pts[j + 1][k], f)));
  }
  return out;
}

/** A flap's outline and stitching, flat on the lid; it hinges on the rim at y = h. */
function flapShape(h, seam) {
  const dir = Math.sign(seam - h);
  return {
    h, dir,
    edge: fillet([[X0, h], [X1, h], [X1, seam], [X0, seam]], [CR, CR, 1.5, 1.5]),
    stitch: fillet([[X0 + 3, h + 3 * dir], [X1 - 3, h + 3 * dir], [X1 - 3, seam - 2.5 * dir], [X0 + 3, seam - 2.5 * dir]], [6, 6, 1, 1]),
  };
}

function mount({ stage, svg, read }, value) {
  const bag = disposer();
  let L = value;
  const C = Cam(45, 0.5, 1.42);
  fit(C, [[BX0, 0, -BZ], [BX, BY, -BZ], [BX, 0, -BZ], [BX0, BY, -BZ], [X0, Y0, CH + 32], [X1, Y0, CH + 32],
    [BX + 3, S, -57], [BX + LMAX + 22, S, LIFT + 10]], 200, 166);
  const P = proj(C), front = facing(C), Pv = (q) => P(q[0], q[1], q[2]);

  const g = mk("g", {}, svg);
  const [br, bi] = rings(BX0, 0, BX, BY, 6, 2);
  put(solid(g), prism(P, front, br, bi, -BZ, 0));
  // The harness, flat: shoulder straps splayed off the top end with a chest strap, leg loops off the bottom.
  const flat = (r, cls, a = 0, cx = 0, cy = 0) => {
    const c = Math.cos(rad(a)), s = Math.sin(rad(a));
    mk("path", { d: poly(r.map((q) => P(cx + (q.u - cx) * c - (q.v - cy) * s, cy + (q.u - cx) * s + (q.v - cy) * c, 0.3))), class: cls }, g);
  };
  for (const [y, a] of [[30, 14], [66, -14]]) {
    flat(rrect(-34, y - 8, 26, y + 8, 8, 6), "", a, 26, y);
    flat(rrect(-28, y - 2.4, 26, y + 2.4, 2.4, 4), "nf", a, 26, y);
  }
  flat(rrect(-12, 30, -6, 66, 1.5, 3), "");
  flat(rrect(-14, 44.5, -4, 51.5, 2, 3), "nf");
  for (const y of [27, 69]) { flat(rrect(130, y - 12, 166, y + 12, 12, 6), ""); flat(rrect(137, y - 6, 159, y + 6, 6, 5), "nf"); }

  // The container is a tray: its far half before the bag, its near walls after, so the bag never shows through.
  const outer = rrect(X0, Y0, X1, Y1, CR, 6), inner = rrect(X0 + WT, Y0 + WT, X1 - WT, Y1 - WT, CR - WT, 6);
  const LR = (pts) => (pts[0][0] <= pts[pts.length - 1][0] ? pts : pts.slice().reverse());
  const cont = mk("g", {}, g);
  mk("path", { d: poly(hull(ringAt(P, outer, 0).concat(ringAt(P, outer, CH)))), class: "sil" }, cont);
  mk("path", { d: poly(ringAt(P, inner, CH)), class: "nf" }, cont);
  mk("path", { d: open(ringAt(P, run(inner, (q) => !front(q)), 2.5)), class: "nf lo" }, cont);

  const bagEl = solid(g);
  const [gr, gi] = rings(X0 + 8, Y0 + 8, X1 - 8, Y1 - 8, 8, 2);
  // Two risers along the bag: the far one whole, the near one in two pieces, square where it was cut.
  const rib = (x0, x1, y, r0, r1, kick = 0) => fillet([[x0, y - 1.8], [x1, y - 1.8 + kick], [x1, y + 1.8 + kick], [x0, y + 1.8]], [r0, r1, r1, r0]);
  const RISERS = [rib(31, 127, S - 9, 1.5, 1.5), rib(31, 71, S + 9, 1.5, 0.5), rib(127, 86, S + 9, 1.5, 0.5, 2.2)];
  const risers = RISERS.map(() => mk("path", {}, bagEl.g)), straps = risers.slice(1);

  const iF = LR(ringAt(P, run(inner, front), CH)), oT = LR(ringAt(P, run(outer, front), CH)), oB = LR(ringAt(P, run(outer, front), 0));
  const near = mk("g", {}, g);
  mk("path", { d: poly([...iF, oT[oT.length - 1], ...oB.slice().reverse(), oT[0]]), class: "fo" }, near);
  mk("path", { d: open(oT), class: "nf lo" }, near);
  mk("path", { d: open(iF), class: "nf" }, near);
  mk("path", { d: open([oT[0], ...oB, oT[oT.length - 1]]), class: "nf sil" }, near);

  const flaps = [flapShape(Y0, S - 0.5), flapShape(Y1, S + 0.5)].map((f) => {
    const fg = mk("g", {}, g);
    return { ...f, g: fg, edge_: mk("path", {}, fg), stitch_: mk("path", { class: "nf lo" }, fg) };
  });
  const [far, nearFlap] = flaps;
  const grommet = mk("circle", { r: 1.3, class: "dot m" }, nearFlap.g);

  const cableG = mk("g", {}, g);
  const cable = mk("path", { class: "nf sil" }, cableG), fray = mk("path", { class: "nf lo" }, cableG);
  const hOut = mk("path", { class: "nf hi" }, cableG), hIn = mk("path", { class: "nf lo" }, cableG);

  const slack = resample(SLACK, M);
  const K = slack.reduce((b, q, i) => (Math.hypot(q[0] - BX, q[2]) < Math.hypot(slack[b][0] - BX, slack[b][2]) ? i : b), 0);
  let taut, H0s, H1s;
  function aimLine() {
    taut = resample([[X1 + 1, S, CH + 3], [BX + L, S, LIFT]], M);
    H0s = Pv(slack[M - 1]); H1s = Pv(taut[M - 1]);
  }
  aimLine();

  const pull = spring(0, { eps: 0.002 }), flapT = tween(0), bagT = tween(BAG0);
  let drawn = "", opened = false, farFront = true;

  function draw(u, th, bt) {
    const key = `${u}|${th}|${bt}|${L}`;
    if (key === drawn) return;
    drawn = key;
    const c = slack.map((q, i) => q.map((v, k) => lerp(v, taut[i][k], u)));
    cable.setAttribute("d", open(c.map(Pv)));
    const e = c[M - 1], q = c[M - 2], n = Math.hypot(e[0] - q[0], e[1] - q[1], e[2] - q[2]);
    // The handle stands in the vertical plane through the cable's end: along T, and across W = T × y.
    const T = [0, 1, 2].map((k) => (e[k] - q[k]) / n), W = [-T[2], 0, T[0]];
    const ring = (r) => poly(r.map(([u, v]) => P(e[0] + T[0] * u + W[0] * v, e[1] + T[1] * u, e[2] + T[2] * u + W[2] * v)));
    hOut.setAttribute("d", ring(D_OUT));
    hIn.setAttribute("d", ring(D_IN));
    // Two strands sprung loose where it rubs the edge, uneven so they read as wear, not a mark.
    fray.setAttribute("d", FRAY.map(([i, pts]) => open(pts.map((o) => P(c[K + i][0] + o[0], c[K + i][1] + o[1], c[K + i][2] + o[2])))).join(""));

    const cs = Math.cos(rad(th)), sn = Math.sin(rad(th));
    for (const fl of flaps) {
      const at = (x, y) => { const d = Math.abs(y - fl.h); return P(x, fl.h + fl.dir * d * cs, CH + d * sn); };
      fl.edge_.setAttribute("d", poly(fl.edge.map((p) => at(p[0], p[1]))));
      fl.stitch_.setAttribute("d", poly(fl.stitch.map((p) => at(p[0], p[1]))));
      if (fl === nearFlap) place(grommet, at(72, S + 2.4));
    }
    // The far flap lies on the lid until it passes upright, then hangs behind the container.
    if (th > 90 === farFront) { farFront = !farFront; (farFront ? nearFlap.g : cont).before(far.g); }

    put(bagEl, prism(P, front, gr, gi, 2, bt));
    risers.forEach((el, i) => el.setAttribute("d", poly(RISERS[i].map((p) => P(p[0], p[1], bt + 0.3)))));
  }

  const B = register(stage, (dt, now) => {
    const m = stepS(pull, dt);
    draw(pull.x, tval(flapT, now), tval(bagT, now));
    return m || !tdone(flapT, now) || !tdone(bagT, now);
  });
  bag.add(B.unregister);

  /** t: how far along the pull the pointer is, 0 to 1, or null when it leaves. */
  function aim(t) {
    pull.t = t ?? 0;
    const o = t != null && t >= PIN;
    if (o !== opened) {
      opened = o;
      const now = performance.now();
      // Opening waits for the cable to come out; closing waits for the bag to sink.
      tset(flapT, o ? OPEN : 0, now, o ? 260 : 300);
      tset(bagT, o ? BAG1 : BAG0, now, o ? 560 : 0);
      hOut.classList.toggle("hi", !o);
      straps.forEach((el) => el.classList.toggle("hi", o));
    }
    read.textContent = t == null ? "rest" : t < 0.15 ? "sealed" : t < PIN ? "pulling" : "line cut";
    B.wake();
  }
  const along = (p) => {
    const dx = H1s[0] - H0s[0], dy = H1s[1] - H0s[1];
    return clamp(((p[0] - H0s[0]) * dx + (p[1] - H0s[1]) * dy) / (dx * dx + dy * dy), 0, 1);
  };
  let last = null;
  bag.add(pointer(stage, { move: (p) => { last = p; aim(along(p)); }, leave: () => { last = null; aim(null); } }));
  bag.add(() => svg.replaceChildren());

  return {
    set: (v) => { L = v; aimLine(); drawn = ""; if (last) aim(along(last)); B.wake(); },
    destroy: bag.dispose,
  };
}

hairline({
  name: "ripcord",
  means: "A packed rig on a bench: pull the slack ripcord and the flaps fall open on a strap cut clean through.",
  rules: [1, 4, 5, 6],
  range: [36, 54, 72],
  tour: [[288, 258], [311, 232], [343, 205], null],
  mount,
});
}
